  - futures -> 0 if isIdxRoot, else 1;
  - forex or basecurrency XAU/XAG/XPT/XPD -> 2;
  - stock/fund/dr -> 4;
  - index -> 5;
  - else 6.

Empirical flags (series):
- var bool sawSat := true on any bar where dayofweek(time, "UTC") == saturday;
- mkt = Auto and sawSat ? 3 : mktS;
- wkend = mkt == 3 and UTC day is Sat or Sun;
- stkETH = mkt == 4 and syminfo.session == session.extended.

Presets (only where the user left the defaults):
